policies:
@id("SUPPORT-001#1")
@aster_rule("SUPPORT-001")
@aster_module("guard.support")
@aster_source_hash("ee8d1f7e02d2371b2dfc55a31a43365ccfa9ff34ae6e8c2492ce556a344155b2")
@aster_outcome("deny")
@aster_reason("suspended principal")
@aster_controls("EU_AI_ACT:ART14")
forbid (principal, action, resource)
when { (principal.roles.contains("suspended")) };

@id("SUPPORT-001#2")
@aster_rule("SUPPORT-001")
@aster_module("guard.support")
@aster_source_hash("ee8d1f7e02d2371b2dfc55a31a43365ccfa9ff34ae6e8c2492ce556a344155b2")
@aster_outcome("require_approval")
@aster_approver("Data Protection Officer")
@aster_reason("customer record deletion")
@aster_controls("EU_AI_ACT:ART14")
forbid (principal, action, resource)
when { !(principal.roles.contains("suspended")) && (action == Aster::Action::"delete_customer_record") };

@id("SUPPORT-001#3")
@aster_rule("SUPPORT-001")
@aster_module("guard.support")
@aster_source_hash("ee8d1f7e02d2371b2dfc55a31a43365ccfa9ff34ae6e8c2492ce556a344155b2")
@aster_outcome("escalate")
@aster_reason("large refund")
@aster_controls("EU_AI_ACT:ART14")
forbid (principal, action, resource)
when { !(principal.roles.contains("suspended")) && !(action == Aster::Action::"delete_customer_record") && ((action == Aster::Action::"issue_refund") && (context has amount && (-9007199254740991 <= context.amount && context.amount <= 9007199254740991) && (context.amount >= 10000))) };

@id("SUPPORT-001#4")
@aster_rule("SUPPORT-001")
@aster_module("guard.support")
@aster_source_hash("ee8d1f7e02d2371b2dfc55a31a43365ccfa9ff34ae6e8c2492ce556a344155b2")
@aster_outcome("allow")
@aster_controls("EU_AI_ACT:ART14")
permit (principal, action, resource)
when { !(principal.roles.contains("suspended")) && !(action == Aster::Action::"delete_customer_record") && (!(action == Aster::Action::"issue_refund") || ((action == Aster::Action::"issue_refund") && (context has amount && (-9007199254740991 <= context.amount && context.amount <= 9007199254740991) && !(context.amount >= 10000)))) };
